import{b as t,O as a,g as i,j as e}from"./chunks/framework.DcaUmd3X.js";const n="/assets/image.BZEu_3Ob.webp",u=JSON.parse('{"title":"使用GitHub","description":"","frontmatter":{},"headers":[],"relativePath":"git/collaboration/github/index.md","filePath":"Git操作手册/4.协作与进阶/01.使用GitHub.md","lastUpdated":1783947942000}'),l={name:"git/collaboration/github/index.md"};function h(r,s,o,p,d,k){return a(),i("div",null,[...s[0]||(s[0]=[e('<h1 id="使用github" tabindex="-1">使用GitHub <a class="header-anchor" href="#使用github" aria-label="Permalink to &quot;使用GitHub&quot;">​</a></h1><blockquote><p>不只是存代码——创建仓库 / 浏览代码 / 参与开源项目</p></blockquote><h2 id="github-是什么" tabindex="-1">GitHub 是什么 <a class="header-anchor" href="#github-是什么" aria-label="Permalink to &quot;GitHub 是什么&quot;">​</a></h2><p>GitHub 是全球最大的代码托管平台，底层是 Git，上面加了一层 Web 界面和协作功能。你的代码存在上面、团队在上面协作、开源社区在上面运转。</p><h2 id="创建自己的仓库" tabindex="-1">创建自己的仓库 <a class="header-anchor" href="#创建自己的仓库" aria-label="Permalink to &quot;创建自己的仓库&quot;">​</a></h2><p>在 GitHub 主页点右上角 <code>+</code> → New repository → 填仓库名 → Create repository。然后跟本地关联的方式有两种，前面创建版本库已经详细讲过：</p><ul><li><strong>本地已有项目</strong> → <code>git init</code> → <code>add</code> → <code>commit</code> → <code>remote add</code> → <code>push</code></li><li><strong>本地没有项目</strong> → <code>git clone 仓库地址</code> 直接拉下来</li></ul><h2 id="仓库页面上能做什么" tabindex="-1">仓库页面上能做什么 <a class="header-anchor" href="#仓库页面上能做什么" aria-label="Permalink to &quot;仓库页面上能做什么&quot;">​</a></h2><p>打开任何一个 GitHub 仓库页面，你会看到这些常用区域：</p><table tabindex="0"><thead><tr><th>区域</th><th>能干嘛</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>浏览代码文件、复制仓库地址</td></tr><tr><td><strong>Issues</strong></td><td>报告 bug、提功能建议</td></tr><tr><td><strong>Pull requests</strong></td><td>看别人提交的 PR、review 代码</td></tr><tr><td><strong>Actions</strong></td><td>看自动化构建和部署状态</td></tr><tr><td><strong>Star</strong></td><td>收藏项目（类似点赞，右上角 ⭐ 按钮）</td></tr><tr><td><strong>Watch</strong></td><td>关注项目，有更新会收到通知</td></tr></tbody></table><p>日常频率最高的是 <strong>Star</strong> 和 <strong>Watch</strong>——看到好项目点 Star 收藏，想关注动态点 Watch。</p><h2 id="参与别人的项目-fork-pr" tabindex="-1">参与别人的项目：Fork + PR <a class="header-anchor" href="#参与别人的项目-fork-pr" aria-label="Permalink to &quot;参与别人的项目：Fork + PR&quot;">​</a></h2><p>假设你想给一个开源项目贡献代码。不能直接往人家仓库里 push——你没权限。正确流程是这样：</p><p><img src="'+n+`" alt="alt text"></p><p>具体操作分五步。</p><h3 id="第一步-fork-仓库" tabindex="-1">第一步：Fork 仓库 <a class="header-anchor" href="#第一步-fork-仓库" aria-label="Permalink to &quot;第一步：Fork 仓库&quot;">​</a></h3><p>打开原作者的 GitHub 仓库页面，点右上角 <strong>Fork</strong> 按钮。GitHub 会在你的账号下创建一个一模一样的副本。</p><h3 id="第二步-clone-到本地" tabindex="-1">第二步：Clone 到本地 <a class="header-anchor" href="#第二步-clone-到本地" aria-label="Permalink to &quot;第二步：Clone 到本地&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:你的用户名/项目名.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 项目名</span></span></code></pre></div><h3 id="第三步-关联原仓库" tabindex="-1">第三步：关联原仓库 <a class="header-anchor" href="#第三步-关联原仓库" aria-label="Permalink to &quot;第三步：关联原仓库&quot;">​</a></h3><p>你的副本不会自动同步原作者的更新。加一个 <code>upstream</code> 远程指向原仓库，方便拉取最新代码：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:原作者/项目名.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># origin    git@github.com:你/项目名.git (fetch)    ← 你的副本，有写权限</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># upstream  git@github.com:作者/项目名.git (fetch)  ← 原仓库，只读</span></span></code></pre></div><p>之后原作者更新了，你可以拉取同步：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream/master</span></span></code></pre></div><p>这就是之前远程仓库那篇说&quot;upstream 留到后面讲&quot;的原因——它主要用于 Fork 工作流。</p><h3 id="第四步-开分支、改代码、推送" tabindex="-1">第四步：开分支、改代码、推送 <a class="header-anchor" href="#第四步-开分支、改代码、推送" aria-label="Permalink to &quot;第四步：开分支、改代码、推送&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-fix-typo</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 改代码...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修复 README 中的拼写错误&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-fix-typo</span></span></code></pre></div><h3 id="第五步-发起-pull-request" tabindex="-1">第五步：发起 Pull Request <a class="header-anchor" href="#第五步-发起-pull-request" aria-label="Permalink to &quot;第五步：发起 Pull Request&quot;">​</a></h3><p>推送到你的 GitHub 副本后，打开仓库页面，GitHub 会提示你发起 Pull Request（简称 PR）。点击 <strong>Compare &amp; pull request</strong>，写清楚你改了什么、为什么改，然后提交。</p><p>PR 的核心就是一句话：<strong>&quot;我改了一些代码，请原作者审阅并合并到你的仓库里。&quot;</strong> 原作者可能会在 PR 下面留言讨论、要求修改。你在本地继续改、继续推，PR 会自动更新。</p><h2 id="用-issue-提需求或报告-bug" tabindex="-1">用 Issue 提需求或报告 bug <a class="header-anchor" href="#用-issue-提需求或报告-bug" aria-label="Permalink to &quot;用 Issue 提需求或报告 bug&quot;">​</a></h2><p>如果你不想改代码，只是想报告一个 bug、提一个功能建议——用 <strong>Issue</strong>。进入仓库的 Issues 标签页，点 <strong>New Issue</strong>，描述你遇到的问题。</p><p>一个好的 Issue 通常包含：<strong>做了什么操作 → 期望什么结果 → 实际发生了什么</strong>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>参与开源的三件套：</p><ol><li><strong>Fork</strong> — 把别人仓库复制到自己的账号下</li><li><strong>PR</strong> — 改完代码，请求原作者合并</li><li><strong>Issue</strong> — 不写代码也能参与：报告 bug、提建议</li></ol><p>流程记住：<strong>Fork → Clone → 开分支改代码 → Push → 发起 PR</strong>。</p><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>找一个简单的开源项目（比如文档类项目），Fork 到自己的账号，Clone 到本地</li><li>创建分支，改一些文字或文档，Push 并发起一个 Pull Request</li><li>给 Fork 的仓库加 <code>upstream</code> 远程，用 <code>git fetch upstream</code> 拉取原仓库的最新更新</li><li>在开源项目里提一个 Issue（如果发现有值得反馈的问题）</li></ol>`,39)])])}const c=t(l,[["render",h]]);export{u as __pageData,c as default};
